//! OUTPUT name reflection and fixed readonly type metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed name=initial type=authored>ready</output><input id=field value=seed></form><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-name-type.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_name_type_canonical_descriptors_brands_and_readonly_type(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),name=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'name'),type=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'type');if(!name||typeof name.get!=='function'||typeof name.set!=='function'||!name.enumerable||!name.configurable||name.get.name!=='get name'||name.get.length!==0||name.set.name!=='set name'||name.set.length!==1||Object.hasOwn(output,'name'))throw 'canonical output name descriptor';if(!type||typeof type.get!=='function'||type.set!==undefined||!type.enumerable||!type.configurable||type.get.name!=='get type'||type.get.length!==0||Object.hasOwn(output,'type')||type.get.call(output)!=='output'||output.type!=='output'||output.name!=='initial')throw 'canonical readonly type';output.type='changed';if(output.type!=='output'||Object.hasOwn(output,'type'))throw 'sloppy readonly type';var caught=false;try{(function(){'use strict';output.type='changed';})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly type';for(var bad of [{},Object.create(HTMLOutputElement.prototype),document.getElementById('label'),document.createElement('div'),document.createElementNS('urn:foreign','output')]){for(var getter of [name.get,type.get]){caught=false;try{getter.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine metadata brand';}}"#);}
#[test]
fn output_name_type_exact_public_name_producers_refresh_native_name_lists(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),a=output.getAttributeNode('name'),raw=document.getElementsByName('A\ud800z'),literal=document.getElementsByName('A�z');output.setAttribute('name','A\ud800z');if(output.name!=='A\ud800z'||a.value!==output.name||raw.length!==1||raw[0]!==output||literal.length||output.matches('[name="A�z"]'))throw 'exact public output name';output.setAttributeNS(null,'name','A�z');if(output.name!=='A�z'||raw.length||literal.length!==1)throw 'explicit null namespace producer';a.value='A\ud800z';if(output.getAttributeNode('name')!==a||output.name!=='A\ud800z'||raw.length!==1||literal.length)throw 'actual Attr exact producer';"#);}
#[test]
fn output_name_type_idl_converts_once_and_keeps_observer_and_association_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),attr=output.getAttributeNode('name'),labels=output.labels,tokens=output.htmlFor,owner=output.form,calls=0,watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});output.name={toString:function(){calls++;return 'A\ud800z';}};var records=watch.takeRecords();if(calls!==1||output.name!=='A\ud800z'||attr.value!==output.name||records.length!==1||records[0].oldValue!=='initial'||records[0].attributeName!=='name'||output.type!=='output'||output.labels!==labels||labels[0].control!==output||output.form!==owner||output.htmlFor!==tokens||tokens.value!=='seed')throw 'native name conversion and independent metadata';"#);}

#[test]
fn output_name_type_native_conversion_reentry_and_author_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),nd=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'name'),td=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'type'),old=output.getAttributeNode('name'),calls=0;output.name={toString:function(){calls++;output.removeAttribute('name');output.setAttribute('name','callback');return 'A\ud800z';}};var actual=output.getAttributeNode('name');if(calls!==1||actual===old||old.ownerElement!==null||old.value!=='initial'||actual.value!=='A\ud800z')throw 'current actual attribute after conversion';var marker={},caught;try{output.name={toString:function(){output.setAttribute('name','effect');throw marker;}};}catch(e){caught=e;}if(caught!==marker||output.name!=='effect')throw 'abrupt completed author effects';caught=false;try{output.name=Symbol('bad');}catch(e){caught=e instanceof TypeError;}if(!caught||actual.value!=='effect')throw 'symbol conversion before publication';output.type={toString:function(){calls++;return 'bad';}};if(calls!==1||output.type!=='output'||output.getAttribute('type')!=='authored')throw 'readonly type never converts';nd.set.call(output,null);if(output.name!=='null')throw 'null DOMString';nd.set.call(output);if(output.name!=='undefined')throw 'missing argument DOMString';var hits=0;try{nd.set.call({},{toString:function(){hits++;return 'bad';}});}catch(e){if(!(e instanceof TypeError))throw e;}if(hits)throw 'brand before conversion';Object.defineProperty(output,'name',{value:'own',writable:true,configurable:true});Object.defineProperty(output,'type',{value:'own type',writable:true,configurable:true});nd.set.call(output,'native');if(output.name!=='own'||nd.get.call(output)!=='native'||output.type!=='own type'||td.get.call(output)!=='output')throw 'own author shadows';delete output.name;delete output.type;Object.defineProperty(HTMLOutputElement.prototype,'name',{get:function(){return 'prototype';},configurable:true});Object.defineProperty(HTMLOutputElement.prototype,'type',{get:function(){return 'prototype type';},configurable:true});if(output.name!=='prototype'||output.type!=='prototype type'||nd.get.call(output)!=='native'||td.get.call(output)!=='output')throw 'prototype overrides';delete HTMLOutputElement.prototype.name;delete HTMLOutputElement.prototype.type;if(output.name!==undefined||output.type!==undefined||nd.get.call(output)!=='native')throw 'deleted canonical descriptors';Object.defineProperty(HTMLOutputElement.prototype,'name',nd);Object.defineProperty(HTMLOutputElement.prototype,'type',td);var count=0;for(var key in output)if(key==='name'||key==='type')count++;if(count!==2||Object.hasOwn(output,'name')||Object.hasOwn(output,'type'))throw 'inherited restored metadata';"#);}
#[test]
fn output_name_type_inert_clone_adoption_no_main_slots_and_import_guard(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('output');source.name='A\ud800z';var a=source.getAttributeNode('name'),copy=source.cloneNode(true),copied=copy.getAttributeNode('name'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);copy.name='B\udfffz';if(source.name!=='A\ud800z'||copy.name!=='B\udfffz'||a===copied||copy.ownerDocument!==target||copied.ownerDocument!==target||source.type!=='output'||copy.type!=='output')throw 'independent cloned and adopted exact metadata';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();assert!(p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("Import supports ordinary HTML containers"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"var xml=new Document(),isolated=xml.createElementNS('http://www.w3.org/1999/xhtml','output');isolated.name='X\ud800z';if(isolated.name!=='X\ud800z'||isolated.type!=='output'||isolated.getAttributeNode('name').ownerDocument!==xml||copy.name!=='B\udfffz')throw 'HTML metadata in XML owner without main slots';"#);assert_eq!(d.nodes.len(),slots);}
#[test]
fn output_name_type_null_namespace_and_other_raw_sinks_keep_their_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output');output.setAttributeNS('urn:attribute','name','foreign');var foreign=output.getAttributeNodeNS('urn:attribute','name'),actual=output.getAttributeNodeNS(null,'name');output.name='A\ud800z';if(actual!==output.getAttributeNodeNS(null,'name')||actual.value!==output.name||foreign.value!=='foreign')throw 'null namespace IDL reflection';var other=document.createElement('meter'),shape=document.createElementNS('http://www.w3.org/2000/svg','svg');"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());for expression in [r#"output.setAttributeNS('urn:attribute','name','A\ud800z');"#,r#"other.setAttribute('name','A\ud800z');"#,r#"shape.setAttribute('name','A\ud800z');"#]{p.begin_job();assert!(p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{expression}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}p.begin_job();run(&mut d,&mut f,&mut p,r#"output.name='B\udfffz';if(output.name!=='B\udfffz'||actual.value!==output.name||foreign.value!=='foreign')throw 'fresh exact reflection recovery';"#);}
#[test]
fn output_name_type_writer_limits_preserve_actual_records_and_recover(){for inert in [false,true]{for expression in [r#"output.name='long A\ud800z B\udfffz';"#,r#"output.setAttribute('name','long A\ud800z B\udfffz');"#,r#"output.setAttributeNS(null,'name','long A\ud800z B\udfffz');"#,r#"attr.textContent='long A\ud800z B\udfffz';"#]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('output');output.name='initial';var attr=output.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"}else{"var output=document.getElementById('output'),attr=output.getAttributeNode('name'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(output.name!=='initial'||attr.value!=='initial'||watch.takeRecords().length)throw 'atomic refused name write';output.name='fresh';if(output.type!=='output'||attr!==output.getAttributeNode('name')||attr.value!=='fresh'||watch.takeRecords().length!==1)throw 'fresh native metadata recovery';");}}}}
#[test]
fn output_name_type_paid_reads_and_fixed_type_string_bounds_recover(){let(mut d,mut f,mut p)=fixture();let owner=node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("output")).unwrap());let state=(p.state.retained,p.state.dom_commits);let strings=p.state.limits.host.string_bytes;for property in ["name","type"]{for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_metadata_get(owner,property).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),state);p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}p.begin_job();run(&mut d,&mut f,&mut p,"if(document.getElementById('output').name!=='initial'||document.getElementById('output').type!=='output')throw 'fresh paid metadata reads';");}
#[test]
fn output_name_type_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var name=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOutputElement.prototype,'name'),type=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOutputElement.prototype,'type'),calls=0;name.set.call(output,'A\ud800z');if(name.get.call(output)!=='A\ud800z'||type.get.call(output)!=='output')throw 'saved child metadata';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-metadata.test/",&crate::navigation::Location::home()).unwrap());for expression in ["name.set.call(output,{toString:function(){calls++;return 'bad';}});","name.get.call(output);","type.get.call(output);"]{p.begin_job();let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://output-name-type.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||output.name!=='A\\ud800z')throw 'origin before conversion';name.set.call(output,'fresh');if(output.name!=='fresh'||type.get.call(output)!=='output')throw 'fresh captured metadata recovery';");}
